// Helper functions
window.getArticlesBySection = function(section, limit) {
  let arts = (typeof ARTICLES_DB !== "undefined" ? ARTICLES_DB : ARTICLES_META).filter(a => a.section === section);
  arts.sort((a, b) => new Date(b.date) - new Date(a.date));
  return limit ? arts.slice(0, limit) : arts;
};

window.getArticleBySlug = function(slug) {
  return (typeof ARTICLES_DB !== "undefined" ? ARTICLES_DB : ARTICLES_META).find(a => a.slug === slug);
};

window.getAllArticles = function(limit) {
  let arts = [...(typeof ARTICLES_DB !== "undefined" ? ARTICLES_DB : ARTICLES_META)];
  arts.sort((a, b) => new Date(b.date) - new Date(a.date));
  return limit ? arts.slice(0, limit) : arts;
};

